def complex_QR_decompose(A, T):
    A_gsl = create_gsl_matrix_complex(np.shape(A)[0], np.shape(A)[1])
    T_gsl = create_gsl_matrix_complex(np.shape(T)[0], np.shape(T)[1])
    for i in range(np.shape(A)[0]):
        for j in range(np.shape(A)[1]):
            A_gsl.setitem(i, j, A[i][j].real)
    for i in range(np.shape(T)[0]):
        for j in range(np.shape(T)[1]):
            T_gsl.setitem(i, j, T[i][j].real)
    status = complex_qr_decomp(A_gsl, T_gsl)
    if status:
        return f"Failed with error code: {status}"
    A_gsl_real = np.zeros((np.shape(A)[0], np.shape(A)[1]), dtype=np.complex128)
    for i in range(np.shape(A)[0]):
        for j in range(np.shape(A)[1]):
            A_gsl_real[i][j] = complex(A_gsl.getitem(i, j), 0.0)
    return str(A_gsl_real.tolist())

