def matrix_to_gsl(matrix):
    m = gsl_matrix(*matrix.shape)
    for i in range(m.rows):
        for j in range(m.cols):
            m.setitem(i, j, matrix[i][j])
    return ctypes.byref(m)
def vector_to_gsl(vector):
    v = gsl_vector(*vector.shape)
    for i in range(v.size):
        v.setitem(i, vector[i])
    return ctypes.byref(v)
def ql_decomposition_and_unpack(matrix, tau):
    A_cblas = matrix_to_gsl(matrix)
